import yaml, json

sigma = {
 "title": "Malicious File Download and Execution - curl to /tmp Followed by Bash",
 "id": "9d3f7a21-5c8e-4b17-a6d0-2e9f4c1b8a76",
 "related": [
   {"id": "qpwn-001", "type": "derived"},
   {"id": "qpwn-002", "type": "derived"},
 ],
 "status": "experimental",
 "description": ("Detects the classic Linux download-and-execute malware delivery pattern in which a "
   "curl or wget transfer process stages a bash script into a world-writable directory such as /tmp "
   "and that same staged path is subsequently executed by a shell. This also covers the one-liner "
   "variant where the download is piped directly into bash. Threat intelligence on Q3 2026 Linux "
   "intrusions attributes this curl-to-/tmp plus bash lineage to botnet stagers and dropper families "
   "responsible for roughly 38 percent of observed compromises, spanning stage 1 download to stage 2 "
   "execution of multi-stage droppers."),
 "author": "Security Detection Engineering",
 "date": "2026-10-27",
 "references": [
   "https://attack.mitre.org/techniques/T1105/",
   "https://attack.mitre.org/techniques/T1059.004/",
 ],
 "DetectionMetadata": {
   "SigmaHQEquivalentRuleNames": [
     "Malicious File Download and Execution - curl to /tmp Followed by Bash"
   ],
   "ATTCKTechniqueIDs": ["T1105","T1059.004","T1059"],
   "ATTCKTacticIDs": ["TA0011","TA0002"],
   "KQLQuery": "",
 },
 "logsource": {"category": "process_creation", "product": "linux"},
 "detection": {
   "sel_curl_download_to_tmp": {
      "Image|endswith": ["/curl", "/wget"],
      "CommandLine|contains|all": ["http","/tmp/"],
      "CommandLine|re": "-{1,2}[oO](\\s|=)\S*[^\\s]*",
   },
   "sel_piped_to_shell": {
      "Image|endswith": ["/curl", "/wget"],
      "CommandLine|contains": ["| bash","|sh"," piping"],
   },
   "sel_bash_exec_staged_script": {
      "ParentImage|endswith": ["/curl", "/wget"],
      "Image|endswith": ["/bash", "/sh", "/dash"],
      "CommandLine|contains": "/tmp/",
   },
   "sel_bash_exec_staged_script_alt": {
      "Image|endswith": ["/bash", "/sh", "/dash"],
      "CommandLine|startswith": ["bash /tmp/","sh /tmp/","/tmp/"],
   },
   "filter_expected_deploy_tooling": {
      "ParentImage|endswith": ["/apt-get","/dpkg","/yum","/dnf","/snap","/cloud-init"],
   },
   "condition": ("(sel_curl_download_to_tmp or sel_piped_to_shell) "
                 "and (sel_bash_exec_staged_script or sel_bash_exec_staged_script_alt) "
                 "and not filter_expected_deploy_tooling"),
   "timeframe": "5m",
 },
 "falsepositives": [
   "Software deployment scripts fetching installers with curl and running them under sudo",
   "Vulnerability scanners and monitoring agents pushing check scripts to /tmp at deploy time",
   "Package manager hooks and legitimate vendor bootstrap tooling",
   "Administrative automation using ansible, puppet and chef to distribute temporary scripts",
 ],
 "level": "high",
 "tags": [
   "attack.command_and_control","attack.t1105",
   "attack.execution","attack.t1059.004",
 ],
}

# KQL reference stored inside metadata must equal the delivered query
kql_main = r'''let window = 5m;
// Stage 1: curl/wget downloading a payload into a world-writable temp directory
let downloads = DeviceProcess
| where FileName in ("curl", "wget")
| where CommandLine matches regex @"-\S*[oO](\s+|=)\S*" and CommandLine contains "/tmp/"
| mv-expand ParsedArgs = split(CommandLine, " ") to typeof(string);
// Stage 2: bash executing a script staged under /tmp by that same download process
let executions = DeviceProcess
| where FileName in ("bash", "sh", "dash") and ParentFileName in ("curl", "wget");
downloads | join kind=inner executions on $left.CommandLine == $right.InitiatingProcessCommandLine;'''
sigma["DetectionMetadata"]["KQLQuery"] = kql_main

y = yaml.safe_dump(sigma, sort_keys=False, allow_unicode=True, width=100)
if y.startswith("---"):
    y = y[3:].lstrip("\n")
doc = yaml.safe_load(y)
assert doc["DetectionMetadata"]["KQLQuery"].strip() == kql_main.strip(), "KQL mismatch"
for lvl in (doc, doc["DetectionMetadata"], doc["detection"]):
    assert isinstance(lvl, dict)
print("YAML round-trip OK; keys:", list(doc))
open("/tmp/sigmarule_final.yml","w").write(y)
json.dump({"sigma_rule": y}, open("/tmp/payload.json","w"))
print("bytes:", len(y), "| condition:", doc["detection"]["condition"])
